using VisualQa.Core;
using Xunit;
namespace VisualQa.Core.Tests;
public sealed class ValidatorsTests { static DesignComponentSpec Design()=>new(){Name="PatientInfo",Elements=[new(){Id="name",Name="Name",Bounds=new(10,5,20,12),Text="Avery",FontSize=16,FontWeight="SemiBold"}]}; static RuntimeComponentSnapshot Runtime(double x=10)=>new(){Elements=[new(){Id="name",Type="TextBlock",Bounds=new(x,5,20,12),Text="Avery",FontSize=16,FontWeight="SemiBold"}]}; [Fact] public void Geometry_Passes_exact_bounds()=>Assert.All(new GeometryValidator().Validate(Design(),Runtime(),new()),x=>Assert.Equal(QaStatus.Pass,x.Status)); [Fact] public void Geometry_Fails_outside_tolerance()=>Assert.Contains(new GeometryValidator().Validate(Design(),Runtime(14),new()),x=>x.Status==QaStatus.Fail); [Fact] public void Matcher_prefers_id()=>Assert.Equal("name",ElementMatcher.Match(Design().Elements[0],Runtime().Elements)!.Id); [Fact] public void Missing_type_is_not_evaluated()=>Assert.Contains(new TypographyValidator().Validate(Design(),new RuntimeComponentSnapshot(),new()),x=>x.Status==QaStatus.NotEvaluated); }
